    var qIn = type === 'stirling' ? legs[2].heat : totalHeatPos;
    var qOutAbs = type === 'stirling' ? Math.abs(legs[0].heat) : totalHeatNegAbs;
    var thermalEfficiency = netWork / Math.max(1e-9, qIn);
